GRANT ALL ON public._q31_test_stage TO service_role; CREATE OR REPLACE FUNCTION public._q31_run_staged_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NEW.run THEN EXECUTE NEW.script; RAISE EXCEPTION 'Suite must abort to roll back fixtures'; END IF; RETURN NEW; END $$; COMMENT ON TABLE public._q31_test_stage IS 'Temporary Q33 rollback-safe verification queue; retire after checks.';